import UIKit

/// Frame sequences of the four animated banner icons (the maple leaf that shrinks into a sprout
/// and grows back, the P2P dots, the QR scan line, the flipping coin), cut from a screen
/// recording of the real mini app at 20 frames per second. Each sheet is a grid of equally sized
/// frames, row by row; the background around the icon is transparent (the frames were cut from a
/// dark-theme recording and matted), so they sit on the banner in either theme. Positions are in the pixels of the 1110x223 banner picture.
struct PampGramFakeCryptoBotIconAnimation {
    let frames: [UIImage]
    /// Where the icon sits in the banner picture, in banner pixels (3 per point).
    let box: CGRect
}

enum PampGramFakeCryptoBotAnimations {
    private struct Sheet {
        let frameCount: Int
        let columns: Int
        let frameWidth: Int
        let frameHeight: Int
        let originX: Int
        let originY: Int
        let data: String
    }

    private static var cache: [String: PampGramFakeCryptoBotIconAnimation] = [:]

    /// `banner` is "autumn", "p2p", "qr" or "exchange".
    static func animation(banner: String) -> PampGramFakeCryptoBotIconAnimation? {
        if let cached = self.cache[banner] {
            return cached
        }
        guard let sheet = self.sheets[banner], let data = Data(base64Encoded: sheet.data), let image = UIImage(data: data), let cgImage = image.cgImage else {
            return nil
        }
        var frames: [UIImage] = []
        for index in 0 ..< sheet.frameCount {
            let rect = CGRect(x: (index % sheet.columns) * sheet.frameWidth, y: (index / sheet.columns) * sheet.frameHeight, width: sheet.frameWidth, height: sheet.frameHeight)
            if let cropped = cgImage.cropping(to: rect) {
                frames.append(UIImage(cgImage: cropped, scale: 3.0, orientation: .up))
            }
        }
        if frames.count != sheet.frameCount {
            return nil
        }
        let result = PampGramFakeCryptoBotIconAnimation(frames: frames, box: CGRect(x: sheet.originX, y: sheet.originY, width: sheet.frameWidth, height: sheet.frameHeight))
        self.cache[banner] = result
        return result
    }

    private static let sheets: [String: Sheet] = [
        "autumn": Sheet(frameCount: 53, columns: 8, frameWidth: 176, frameHeight: 178, originX: 44, originY: 22, data: ""),
        "p2p": Sheet(frameCount: 33, columns: 8, frameWidth: 164, frameHeight: 154, originX: 50, originY: 34, data: ""),
        "qr": Sheet(frameCount: 36, columns: 8, frameWidth: 164, frameHeight: 154, originX: 50, originY: 34, data: ""),
        "exchange": Sheet(frameCount: 38, columns: 8, frameWidth: 159, frameHeight: 158, originX: 53, originY: 38, data: "")
    ]
}
